/**
 * Đẩy nhiều profiles lên Cloud (Tối ưu hóa)
 */
async pushProfiles(profiles) {
  const user = auth.currentUser;
  if (!user) throw new Error("Chưa đăng nhập Firebase");

  // Firestore Lite không hỗ trợ writeBatch, dùng Promise.all với giới hạn
  const promises = profiles.map(profile => {
    const profileRef = doc(db, `users/${user.uid}/profiles`, profile.id);
    return setDoc(profileRef, {
      ...profile,
      updatedAt: serverTimestamp()
    }, { merge: true });
  });

  return await Promise.all(promises);
},

/**
 * Lấy tất cả profiles từ Cloud
 */
async pullProfiles() {
  const user = auth.currentUser;
  if (!user) return [];

  const profilesCol = collection(db, `users/${user.uid}/profiles`);
  const snapshot = await getDocs(profilesCol);

  return snapshot.docs.map(doc => ({
    ...doc.data(),
    id: doc.id
  }));
},

