import { Storage } from './storage.js';
import { SK_ADDRESS_LEARNING } from '../core/constants.js';

/**
 * LocalClassifier: Bộ phân loại dữ liệu dựa trên kinh nghiệm người dùng.
 * Giúp máy "học" từ các thao tác sửa lỗi hoặc gán dữ liệu thủ công.
 */
export const LocalClassifier = {
    // Chìa khóa lưu trữ trong Storage
    STORAGE_KEY: 'vnpt_data_learning_db',

    /**
     * Lưu một mẫu học mới
     * @param {string} rawValue - Giá trị thô ban đầu
     * @param {string} fieldKey - Trường dữ liệu được gán (ví dụ: 'mst', 'name')
     * @param {string} context - Ngữ cảnh (tên trang web hoặc loại form)
     */
    async learn(rawValue, fieldKey, context = 'global') {
        if (!rawValue || !fieldKey) return;

        const db = Storage.get(this.STORAGE_KEY) || {};
        const cleanValue = String(rawValue).trim().toLowerCase();

        // Tạo khóa dựa trên nội dung và ngữ cảnh
        if (!db[fieldKey]) db[fieldKey] = {};

        // Lưu mẫu: { "giá trị thô": { frequency: 1, lastUsed: timestamp } }
        if (!db[fieldKey][cleanValue]) {
            db[fieldKey][cleanValue] = {
                count: 1,
                lastUpdate: Date.now()
            };
        } else {
            db[fieldKey][cleanValue].count++;
            db[fieldKey][cleanValue].lastUpdate = Date.now();
        }

        Storage.set(this.STORAGE_KEY, db);
        console.log(`[LocalClassifier] Đã học: "${cleanValue}" -> ${fieldKey}`);
    },

    /**
     * Dự đoán trường dữ liệu dựa trên giá trị thô
     * @param {string} rawValue 
     * @returns {string|null} fieldKey
     */
    predict(rawValue) {
        const db = Storage.get(this.STORAGE_KEY) || {};
        const cleanValue = String(rawValue).trim().toLowerCase();

        let bestMatch = { fieldKey: null, count: 0 };

        for (const [fieldKey, patterns] of Object.entries(db)) {
            if (patterns[cleanValue]) {
                if (patterns[cleanValue].count > bestMatch.count) {
                    bestMatch = { fieldKey, count: patterns[cleanValue].count };
                }
            }
        }

        return bestMatch.fieldKey;
    },

    /**
     * Gợi ý toàn bộ các trường cho một cụm text lớn (Raw Data)
     * @param {string} fullText 
     */
    classifyRawText(fullText) {
        // Tách text thành các dòng hoặc cụm từ dựa trên dấu phẩy, gạch ngang, xuống dòng
        const parts = fullText.split(/[\n,;|-]/).map(p => p.trim()).filter(p => p.length > 2);
        const results = {};

        parts.forEach(part => {
            const predictedField = this.predict(part);
            if (predictedField) {
                results[predictedField] = part;
            }
        });

        return results;
    }
};

