import { LocalClassifier } from '../../utils/localClassifier.js';

/**
 * Lời nhắc hệ thống chuyên dụng cho văn bản thô (Raw Text)
 */
const getRawTextSystemPrompt = (localExperience = {}) => {
    let fieldsHint = '';
    for (const [key, label] of Object.entries(DEFAULT_LABELS)) {
        const pKey = key.split(',')[0].trim();
        if (REQUIRED_KEYS.includes(pKey)) {
            fieldsHint += `    "${pKey}": "${label}",\n`;
        }
    }

    // Nhúng kinh nghiệm học được vào Prompt để Gemini làm tốt hơn
    let experienceHint = "";
    if (Object.keys(localExperience).length > 0) {
        experienceHint = `\nLƯU Ý KẾT QUẢ TỪ LẦN TRƯỚC (Dùng để tham khảo): ${JSON.stringify(localExperience)}`;
    }

    return `Bạn là một chuyên gia trích xuất dữ liệu từ văn bản thô (tin nhắn, email, ghi chú).
Nhiệm vụ: Tìm thông tin của KHÁCH HÀNG (BÊN A) từ văn bản được cung cấp. Bỏ qua thông tin của nhân viên VNPT hoặc Bên B.
${experienceHint}

CHỈ TRẢ VỀ JSON THUẦN TÚY.
... (giữ nguyên quy tắc cũ)`;
};

/**
 * Thực hiện trích xuất thông tin từ đoạn text thô.
 * Kết hợp Local Experience (Học từ người dùng) + Gemini AI.
 */
export async function extractFieldsFromText(rawText, apiKey, modelName = 'gemini-2.0-flash') {
    if (!rawText || !rawText.trim()) throw new Error("Vui lòng nhập nội dung văn bản cần phân loại.");

    // 1. Thử dùng LocalClassifier để lấy những gì đã "học" được
    const localMatches = LocalClassifier.classifyRawText(rawText);

    // 2. Gọi Gemini để phân tích toàn bộ, có kèm theo "kinh nghiệm" địa phương
    const aiResult = await callGemini({
        apiKey,
        model: modelName,
        systemInstruction: getRawTextSystemPrompt(localMatches),
        userText: `Hãy phân loại thông tin từ đoạn văn bản sau đây: \n\n${rawText}`
    });

    // 3. Ưu tiên Local Match nếu kết quả AI trả về rỗng cho trường đó
    const finalResult = { ...aiResult };
    for (const [key, val] of Object.entries(localMatches)) {
        if (!finalResult[key]) {
            finalResult[key] = val;
        }
    }

    return finalResult;
}

