/**
 * @file tokenTracker.js
 * @desc Tiện ích quản lý, làm sạch văn bản và ước tính Token trước khi gửi AI.
 */

export const TokenTracker = {
    /**
     * Làm sạch văn bản để giảm bớt dung lượng thừa (tiết kiệm token)
     * @param {string} text 
     */
    cleanText(text) {
        if (!text) return "";

        return text
            .replace(/\r\n/g, '\n') // Chuẩn hóa xuống dòng
            .replace(/[ \t]+/g, ' ') // Gom nhiều khoảng trắng/tab thành 1
            .replace(/\n\s*\n/g, '\n') // Loại bỏ các dòng trống liên tiếp
            .trim();
    },

    /**
     * Ước tính số lượng Token (Xấp xỉ)
     * Tiếng Việt trung bình 1 token ~ 1.5 đến 2 ký tự tùy độ phức tạp
     * @param {string} text 
     * @returns {number}
     */
    estimateTokens(text) {
        if (!text) return 0;
        const charCount = text.length;
        // Hệ số an toàn: 1 token cho mỗi 1.5 ký tự tiếng Việt
        return Math.ceil(charCount / 1.5);
    },

    /**
     * Cắt bớt văn bản nếu vượt quá giới hạn an toàn
     * @param {string} text 
     * @param {number} maxTokens 
     */
    truncateToLimit(text, maxTokens = 4000) {
        const estimated = this.estimateTokens(text);
        if (estimated <= maxTokens) return text;

        const charLimit = Math.floor(maxTokens * 1.5);
        console.warn(`[TokenTracker] Văn bản quá dài (${estimated} tokens). Đã cắt bớt còn ${maxTokens}.`);
        return text.substring(0, charLimit) + "... [Dữ liệu bị cắt bớt do quá dài]";
    },

    /**
     * Log thông tin sử dụng token để theo dõi chi phí
     */
    logUsage(feature, text, response) {
        const inputTokens = this.estimateTokens(text);
        const outputTokens = response ? this.estimateTokens(JSON.stringify(response)) : 0;

        console.group(`📊 AI Usage Tracker: ${feature}`);
        console.log(`Input Estimate: ${inputTokens} tokens`);
        console.log(`Output Estimate: ${outputTokens} tokens`);
        console.log(`Total: ${inputTokens + outputTokens} tokens`);
        console.groupEnd();

        return { inputTokens, outputTokens };
    }
};

