/**
 * Gọi API Gemini để xử lý nội dung (Có cơ chế Retry).
 */
export async function callGemini(options, retryCount = 0) {
    const MAX_RETRIES = 2; // Thử lại tối đa 2 lần (tổng cộng 3 lần gọi)

    return new Promise((resolve, reject) => {
        const { apiKey, model, systemInstruction, userText, fileData, filesData } = options;
        if (!apiKey) return reject("Vui lòng nhập API Key Gemini trong Cài đặt.");

        // LÀM SẠCH VÀ ƯỚC TÍNH TOKEN TRƯỚC KHI GỬI
        const cleanedUserText = TokenTracker.cleanText(userText);
        const truncatedUserText = TokenTracker.truncateToLimit(cleanedUserText, 12000);

        const apiUrl = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;

        const requestData = {
            system_instruction: { parts: [{ text: systemInstruction }] },
            contents: [{ parts: [{ text: truncatedUserText }] }],
            generation_config: { response_mime_type: "application/json" }
        };

        // ... (phần xử lý fileData và filesData giữ nguyên)

        const attemptCall = () => {
            if (typeof GM_xmlhttpRequest !== 'undefined') {
                GM_xmlhttpRequest({
                    method: "POST",
                    url: apiUrl,
                    headers: { "Content-Type": "application/json" },
                    data: JSON.stringify(requestData),
                    timeout: 30000,
                    onload: (response) => {
                        if (response.status >= 200 && response.status < 300) {
                            // Xử lý thành công...
                            try {
                                const resObj = JSON.parse(response.responseText);
                                const textResponse = resObj?.candidates?.[0]?.content?.parts?.[0]?.text;
                                handleResponse(textResponse);
                            } catch (e) { reject("Lỗi Parse kết quả từ Gemini API."); }
                        } else if ((response.status >= 500 || response.status === 429) && retryCount < MAX_RETRIES) {
                            // Lỗi Server hoặc Too Many Requests -> Thử lại sau 2s
                            console.warn(`[Gemini] Lỗi ${response.status}. Đang thử lại lần ${retryCount + 1}...`);
                            setTimeout(() => resolve(callGemini(options, retryCount + 1)), 2000);
                        } else {
                            reject(`API Gemini lỗi (${response.status}): ${response.responseText}`);
                        }
                    },
                    ontimeout: () => {
                        if (retryCount < MAX_RETRIES) {
                            console.warn(`[Gemini] Quá hạn 30s. Đang thử lại lần ${retryCount + 1}...`);
                            resolve(callGemini(options, retryCount + 1));
                        } else { reject("Quá hạn thời gian gọi API (30s)"); }
                    },
                    onerror: () => {
                        if (retryCount < MAX_RETRIES) {
                            setTimeout(() => resolve(callGemini(options, retryCount + 1)), 2000);
                        } else { reject("Lỗi kết nối đến Google Gemini API."); }
                    }
                });
            } else {
                // Fetch cho môi trường dev
                fetch(apiUrl, { /* ... */ })
                    .then(r => {
                        if (!r.ok && (r.status >= 500 || r.status === 429) && retryCount < MAX_RETRIES) {
                            return setTimeout(() => resolve(callGemini(options, retryCount + 1)), 2000);
                        }
                        return r.json();
                    })
                    // ...
            }
        };

        const handleResponse = (textResponse) => {
            if (textResponse) {
                try {
                    let cleanJson = textResponse.replace(/```json/g, '').replace(/```/g, '').trim();
                    resolve(JSON.parse(cleanJson));
                } catch (e) { reject("AI trả về kết quả không đúng cấu hình JSON."); }
            } else { reject("AI không trả về kết quả hợp lệ."); }
        };

        attemptCall();
    });
}

