  const user = auth.currentUser;
  if (!user) throw new Error("Chưa đăng nhập Firebase");

  // Nếu offline, lưu vào hàng đợi chờ đồng bộ sau
  if (!this.isOnline()) {
    this.addToSyncQueue('profiles', profiles);
    throw new Error("Đang Offline. Dữ liệu đã được đưa vào hàng đợi đồng bộ.");
  }

  const promises = profiles.map(profile => {
    const profileRef = doc(db, `users/${user.uid}/profiles`, profile.id);
    return setDoc(profileRef, {
      ...profile,
      updatedAt: serverTimestamp()
    }, { merge: true });
  });

  return await Promise.all(promises);
},

/**
 * Thêm dữ liệu vào hàng đợi đồng bộ (Local Storage)
 */
addToSyncQueue(type, data) {
  const queue = JSON.parse(localStorage.getItem('vnpt_sync_queue') || '[]');
  queue.push({
    type,
    data,
    timestamp: Date.now()
  });
  localStorage.setItem('vnpt_sync_queue', JSON.stringify(queue));
  console.log(`[OfflineSync] Đã thêm ${type} vào hàng đợi.`);
},

/**
 * Xử lý hàng đợi khi có mạng lại
 */
async processSyncQueue() {
  if (!this.isOnline() || !auth.currentUser) return;

  const queue = JSON.parse(localStorage.getItem('vnpt_sync_queue') || '[]');
  if (queue.length === 0) return;

  console.log(`[OfflineSync] Đang xử lý ${queue.length} yêu cầu chờ...`);

  for (const item of queue) {
    try {
      if (item.type === 'profiles') await this.pushProfiles(item.data);
      if (item.type === 'config') await this.pushGlobalConfig(item.data);
      // Xóa mục đã xong
      const currentQueue = JSON.parse(localStorage.getItem('vnpt_sync_queue') || '[]');
      currentQueue.shift();
      localStorage.setItem('vnpt_sync_queue', JSON.stringify(currentQueue));
    } catch (err) {
      console.error("[OfflineSync] Lỗi khi xử lý item:", err);
      break; 
    }
  }
},

