import { Storage } from '../utils/storage.js';
import { showToast } from './toast.js';

export const OnboardingService = {
    STORAGE_KEY: 'vnpt_onboarding_done',

    steps: [
        {
            element: '#vnpt-btn-scan',
            title: '🚀 Quét dữ liệu (Alt+S)',
            content: 'Mở trang web VNPT và nhấn nút này để tự động lấy toàn bộ thông tin hồ sơ vào bảng.'
        },
        {
            element: '#vnpt-fields-container',
            title: '📊 Bảng dữ liệu thông minh',
            content: 'Dữ liệu được lưu tại đây. Bạn có thể sửa trực tiếp, máy sẽ tự "học" thói quen của bạn!'
        },
        {
            element: '#vnpt-btn-ai-mode',
            title: '🤖 AI Scanner',
            content: 'Dán văn bản thô hoặc kéo thả file PDF vào đây. AI Gemini sẽ tự bóc tách thông tin cho bạn.'
        },
        {
            element: '#vnpt-btn-more',
            title: '⚙️ Cài đặt & Đồng bộ',
            content: 'Nơi cấu hình API Key, Phím tắt và Đồng bộ Cloud để dùng dữ liệu trên nhiều máy tính.'
        }
    ],

    currentStep: 0,

    init() {
        const isDone = Storage.get(this.STORAGE_KEY);
        if (isDone) return;

        // Đợi UI ổn định rồi bắt đầu
        setTimeout(() => this.startTour(), 3000);
    },

    startTour() {
        this.currentStep = 0;
        this.showStep();
    },

    showStep() {
        const step = this.steps[this.currentStep];
        const target = document.querySelector(step.element);

        if (!target) {
            this.nextStep();
            return;
        }

        // Tạo overlay hướng dẫn
        this.removeOldStep();

        const rect = target.getBoundingClientRect();
        const tooltip = document.createElement('div');
        tooltip.id = 'vnpt-onboarding-tooltip';
        tooltip.innerHTML = `
            <div class="ob-header">${step.title}</div>
            <div class="ob-content">${step.content}</div>
            <div class="ob-actions">
                <button id="ob-btn-skip">Bỏ qua</button>
                <button id="ob-btn-next">${this.currentStep === this.steps.length - 1 ? 'Hoàn tất' : 'Tiếp theo'}</button>
            </div>
            <div class="ob-arrow"></div>
        `;

        Object.assign(tooltip.style, {
            position: 'fixed',
            top: (rect.bottom + 15) + 'px',
            right: (window.innerWidth - rect.right) + 'px',
            zIndex: '1000001',
            width: '240px',
            background: 'white',
            padding: '12px',
            borderRadius: '12px',
            boxShadow: '0 10px 30px rgba(0,0,0,0.2)',
            border: '2px solid #1a73e8',
            fontFamily: 'sans-serif',
            animation: 'fadeInUp 0.3s ease'
        });

        document.body.appendChild(tooltip);

        // Highlight target
        target.classList.add('vnpt-ob-highlight');

        document.getElementById('ob-btn-next').onclick = () => this.nextStep();
        document.getElementById('ob-btn-skip').onclick = () => this.finishTour();
    },

    nextStep() {
        this.currentStep++;
        if (this.currentStep < this.steps.length) {
            this.showStep();
        } else {
            this.finishTour();
        }
    },

    removeOldStep() {
        const old = document.getElementById('vnpt-onboarding-tooltip');
        if (old) old.remove();
        document.querySelectorAll('.vnpt-ob-highlight').forEach(el => el.classList.remove('vnpt-ob-highlight'));
    },

    finishTour() {
        this.removeOldStep();
        Storage.set(this.STORAGE_KEY, true);
        showToast("🎉 Chúc mừng! Bạn đã sẵn sàng sử dụng VNPT PRO.");
    }
};

// CSS bổ sung cho Onboarding
export const onboardingStyles = `
    @keyframes fadeInUp {
        from { opacity: 0; transform: translateY(10px); }
        to { opacity: 1; transform: translateY(0); }
    }
    #vnpt-onboarding-tooltip .ob-header { font-weight: 800; color: #1a73e8; font-size: 13px; margin-bottom: 6px; }
    #vnpt-onboarding-tooltip .ob-content { font-size: 11px; color: #5f6368; line-height: 1.4; margin-bottom: 12px; }
    #vnpt-onboarding-tooltip .ob-actions { display: flex; justify-content: space-between; }
    #vnpt-onboarding-tooltip button { 
        padding: 4px 10px; border-radius: 6px; border: none; font-size: 10px; font-weight: 700; cursor: pointer;
    }
    #ob-btn-skip { background: #f1f3f4; color: #5f6368; }
    #ob-btn-next { background: #1a73e8; color: white; }
    .vnpt-ob-highlight { 
        position: relative; z-index: 1000002 !important; 
        box-shadow: 0 0 0 4px rgba(26, 115, 232, 0.4) !important;
        pointer-events: none;
    }
    #vnpt-onboarding-tooltip .ob-arrow {
        position: absolute; top: -8px; right: 20px;
        width: 0; height: 0; 
        border-left: 8px solid transparent; border-right: 8px solid transparent;
        border-bottom: 8px solid #1a73e8;
    }
`;

