/**
 * Đẩy cấu hình tổng quát lên Cloud (Bao gồm cả API Keys đã mã hóa)
 */
async pushGlobalConfig(config, apiKeys = null) {
    const user = auth.currentUser;
    if (!user) return;

    const finalConfig = { ...config };

    // Nếu có API Keys, mã hóa và nhúng luôn vào config
    if (apiKeys) {
        finalConfig.secrets = {};
        for (const [key, val] of Object.entries(apiKeys)) {
            finalConfig.secrets[key] = encrypt(val);
        }
    }

    const configRef = doc(db, `users/${user.uid}/settings`, "config");
    await setDoc(configRef, {
        ...finalConfig,
        updatedAt: serverTimestamp()
    }, { merge: true });
},

/**
 * Khôi phục cấu hình tổng quát từ Cloud (Bao gồm giải mã API Keys)
 */
async pullGlobalConfig() {
    const user = auth.currentUser;
    if (!user) return null;

    const configRef = doc(db, `users/${user.uid}/settings`, "config");
    const snap = await getDoc(configRef);
    if (!snap.exists()) return null;

    const data = snap.data();

    // Nếu có phần bí mật (secrets), giải mã ngược lại
    if (data.secrets) {
        data.decryptedKeys = {};
        for (const [key, val] of Object.entries(data.secrets)) {
            data.decryptedKeys[key] = decrypt(val);
        }
    }

    return data;
},

